<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CheckoutService;
use EventMenu\Services\OrderFulfillmentService;

$pdo=Database::connection();$token=trim((string)($_GET['t']??''));$error=null;
function p_money(int$c):string{return 'R$ '.number_format($c/100,2,',','.');}
function p_qty(float|int|string$v):string{$q=(float)$v;return abs($q-round($q))<0.0005?(string)(int)round($q):rtrim(rtrim(number_format($q,3,',','.'),'0'),',');}
function p_channel(string$c):string{return match($c){'pickup'=>'Retirada no local','counter'=>'Balcão / PDV','delivery'=>'Delivery','table'=>'Mesa / comanda',default=>$c};}
function allowed_checkout_url(string$provider,string$url):bool{$p=parse_url($url);if(($p['scheme']??'')!=='https'||empty($p['host']))return false;$h=strtolower($p['host']);$allowed=['stripe'=>['stripe.com'],'mercadopago'=>['mercadopago.com','mercadopago.com.br'],'pagbank'=>['pagseguro.uol.com.br','pagbank.com.br']];foreach($allowed[$provider]??[]as$suffix){if($h===$suffix||str_ends_with($h,'.'.$suffix))return true;}return false;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';
    else{try{$provider=(string)($_POST['provider']??'');$checkout=(new CheckoutService())->create($token,$provider);if(!allowed_checkout_url($checkout['provider'],$checkout['url']))throw new RuntimeException('URL de checkout rejeitada por segurança.');header('Location: '.$checkout['url'],true,303);exit;}catch(Throwable$e){$error=$e->getMessage();}}
}
$s=$pdo->prepare('SELECT o.*,t.name tenant_name,t.slug tenant_slug,c.name customer_name FROM orders o JOIN tenants t ON t.id=o.tenant_id LEFT JOIN customers c ON c.id=o.customer_id WHERE o.public_token=? AND t.status="active" LIMIT 1');$s->execute([$token]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Pedido não encontrado.');}
$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$items->execute([$order['id']]);$items=$items->fetchAll();
$g=$pdo->prepare('SELECT provider FROM payment_gateways WHERE tenant_id=? AND active=1 AND provider IN ("stripe","pagbank","mercadopago") ORDER BY provider');$g->execute([$order['tenant_id']]);$gateways=$g->fetchAll(PDO::FETCH_COLUMN);
$tickets=$pdo->prepare('SELECT t.*,e.name event_name,b.name batch_name FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id WHERE t.order_id=? ORDER BY t.id');$tickets->execute([$order['id']]);$tickets=$tickets->fetchAll();
$fulfillment=new OrderFulfillmentService();$hasOrderQr=$fulfillment->supportsChannel((string)$order['channel'])&&!empty($order['public_token']);$qrDataUri=$hasOrderQr?$fulfillment->qrDataUri((string)$order['public_token'],310):null;
try{$progress=$hasOrderQr?$fulfillment->publicProgress((int)$order['tenant_id'],(int)$order['id']):null;}catch(Throwable){$progress=null;}
$css=Security::e(app_url('assets/app.css'));
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b0f14"><meta http-equiv="Cache-Control" content="no-store"><title>Pedido #<?= (int)$order['id'] ?> — EventMenu</title><link rel="stylesheet" href="<?= $css ?>"><style>
.public-shell{max-width:820px;margin:24px auto;padding:16px}.order-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.pay-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}.ticket-link{display:block;margin:8px 0}.qr-card{display:grid;grid-template-columns:250px minmax(0,1fr);gap:22px;align-items:center;border:1px solid rgba(244,185,66,.28);background:linear-gradient(145deg,rgba(244,185,66,.09),rgba(16,23,34,.96));border-radius:22px;padding:20px;margin:18px 0}.qr-box{background:#fff;border-radius:18px;padding:12px;display:grid;place-items:center}.qr-box img{width:100%;height:auto;display:block}.qr-card h2{margin:3px 0 8px}.qr-card p{line-height:1.5}.progress-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.progress-box{background:#0d141f;border:1px solid #263146;border-radius:14px;padding:12px}.progress-box small,.progress-box strong{display:block}.progress-box small{color:#98a4b8;font-size:11px}.progress-box strong{font-size:20px;margin-top:3px}.channel-badge{display:inline-flex;padding:6px 9px;border-radius:999px;background:#202a3a;color:#dfe5ee;font-size:11px;font-weight:800}@media(max-width:640px){.qr-card{grid-template-columns:1fr}.qr-box{max-width:270px;margin:auto}.progress-grid{grid-template-columns:1fr 1fr 1fr}.order-head{flex-direction:column}}
</style></head><body><main class="public-shell"><div class="brand">EventMenu <span>Premium</span></div><p class="muted"><?= Security::e($order['tenant_name']) ?></p><section class="card"><div class="order-head"><div><span class="channel-badge"><?= Security::e(p_channel((string)$order['channel'])) ?></span><h1>Pedido #<?= (int)$order['id'] ?></h1><p class="muted"><?= Security::e($order['customer_name']??'Cliente') ?></p></div><span class="badge"><?= Security::e((string)$order['payment_status']) ?></span></div><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?>
<div class="table-wrap"><table class="table"><tbody><?php foreach($items as$i):?><tr><td><?= Security::e($i['name_snapshot']) ?> × <?= p_qty($i['quantity']) ?></td><td><?= p_money((int)$i['total_cents']) ?></td></tr><?php endforeach;?><?php if((int)$order['discount_cents']>0):?><tr><td>Desconto</td><td>- <?= p_money((int)$order['discount_cents']) ?></td></tr><?php endif;?><?php if((int)($order['delivery_fee_cents']??0)>0):?><tr><td>Taxa de entrega</td><td><?= p_money((int)$order['delivery_fee_cents']) ?></td></tr><?php endif;?><tr><td><strong>Total</strong></td><td><strong><?= p_money((int)$order['total_cents']) ?></strong></td></tr></tbody></table></div>

<?php if($hasOrderQr):?><section class="qr-card"><div class="qr-box"><img src="<?= Security::e((string)$qrDataUri) ?>" alt="QR do pedido #<?= (int)$order['id'] ?>"></div><div><span class="eyebrow">QR DO PEDIDO</span><h2><?= $order['channel']==='pickup'?'Apresente na retirada':'Guarde este QR' ?></h2><p><?php if($order['channel']==='pickup'):?>Quando chegar ao estabelecimento, apresente este QR ao responsável. Ele verá os itens do pedido e registrará somente o que você retirar naquele momento.<?php elseif($order['channel']==='counter'):?>Apresente este QR ao responsável pela entrega dos produtos.<?php else:?>Este QR identifica o pedido para conferência da equipe responsável.<?php endif;?></p><?php if((string)$order['payment_status']!=='paid'&&(int)$order['total_cents']>0):?><div class="alert error"><strong>Pagamento pendente.</strong> O QR identifica o pedido, mas o sistema não permitirá liberar produtos antes da confirmação do pagamento.</div><?php endif;?><?php if($progress):?><div class="progress-grid"><div class="progress-box"><small>Pedido</small><strong><?= p_qty($progress['ordered_quantity']) ?></strong></div><div class="progress-box"><small>Já retirado</small><strong><?= p_qty($progress['fulfilled_quantity']) ?></strong></div><div class="progress-box"><small>Falta</small><strong><?= p_qty($progress['remaining_quantity']) ?></strong></div></div><?php if($progress['status']==='partial'):?><p class="muted">Retirada parcial registrada. O mesmo QR continua válido para buscar o restante.</p><?php elseif($progress['status']==='fulfilled'):?><div class="alert ok">Todos os itens deste pedido já foram entregues.</div><?php endif;?><?php endif;?></div></section><?php elseif($order['channel']==='table'):?><div class="alert ok">Pedido vinculado à mesa/comanda. Não é necessário QR de retirada.</div><?php endif;?>

<?php if($order['payment_status']==='paid'):?><div class="alert ok"><?= (int)$order['total_cents']===0?'Pedido gratuito confirmado.':'Pagamento confirmado pelo servidor.' ?></div><?php if($tickets):?><h2>Seus ingressos</h2><?php foreach($tickets as$t):$ticketUrl=app_url('ingresso.php?t='.rawurlencode((string)$t['qr_token']));?><a class="button secondary ticket-link" href="<?= Security::e($ticketUrl) ?>">Abrir ingresso <?= Security::e($t['code']) ?> · <?= Security::e($t['status']) ?></a><?php endforeach;?><?php endif;?><?php elseif(!in_array($order['status'],['cancelled','completed'],true)&&((int)$order['total_cents']>0)):?><h2>Escolha como pagar</h2><?php if($gateways):?><div class="pay-grid"><?php foreach($gateways as$provider):?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="provider" value="<?= Security::e($provider) ?>"><button class="primary" style="width:100%">Pagar com <?= Security::e(['stripe'=>'Stripe','mercadopago'=>'Mercado Pago','pagbank'=>'PagBank'][$provider]??$provider) ?></button></form><?php endforeach;?></div><p class="muted">A confirmação só ocorre após validação do webhook e consulta do pagamento no provedor.</p><?php else:?><div class="alert">Nenhum pagamento online foi habilitado por esta empresa.</div><?php endif;?><?php elseif((int)$order['total_cents']===0):?><div class="alert error">Este pedido gratuito ainda não foi confirmado. Atualize a página; se persistir, refaça a reserva.</div><?php elseif($order['status']==='cancelled'):?><div class="alert error">Este pedido foi cancelado.</div><?php endif;?></section></main><?php if(!in_array((string)$order['status'],['cancelled','completed'],true)):?><script>setTimeout(()=>location.reload(),20000);</script><?php endif;?></body></html>